/** Internal type. DO NOT USE DIRECTLY. */
type Exact<T extends { [key: string]: unknown }> = { [K in keyof T]: T[K] };
/** Internal type. DO NOT USE DIRECTLY. */
export type Incremental<T> = T | { [P in keyof T]?: P extends ' $fragmentName' | '__typename' ? T[P] : never };
import type { TypedDocumentNode as DocumentNode } from '@graphql-typed-document-node/core';
export type AutoTopUpInput = {
  /** Micro-USD. Required when enabling. */
  amountMicros?: string | null | undefined;
  enabled: boolean;
  /** Micro-USD. Required when enabling. */
  thresholdMicros?: string | null | undefined;
};

/** Granularity of an activity series. Buckets start on UTC boundaries. */
export type Bucket =
  | 'DAY'
  | 'HOUR';

export type CreateApiKeyInput = {
  expiresAt?: string | null | undefined;
  /** Restrict the key to these model ids. Omit for all. */
  modelIds?: Array<string> | null | undefined;
  name: string;
  requestsPerMinute?: number | null | undefined;
  spendLimitMicros?: string | null | undefined;
  tokensPerMinute?: number | null | undefined;
  workspaceId: string | number;
};

export type CreateCheckoutInput = {
  /** Micro-USD, a whole number of cents, at least `minTopUpMicros`. */
  amountMicros: string;
  workspaceId: string | number;
};

export type CreditTransactionKind =
  | 'ADJUSTMENT'
  | 'AUTO_TOPUP'
  | 'PURCHASE'
  | 'REFUND'
  | 'USAGE';

/** Whether the platform currently publishes a bundle for this endpoint, and whether it is inside the freshness window. A statement about publication only — the router never reports a verification verdict. */
export type EvidenceState =
  | 'NOT_PUBLISHED'
  | 'PUBLISHED'
  | 'STALE';

export type GatekeeperArch =
  | 'AMD64'
  | 'ARM64';

export type GatekeeperOs =
  | 'LINUX'
  | 'MACOS'
  | 'WINDOWS';

export type GenerationFilter = {
  apiKeyIds?: Array<string | number> | null | undefined;
  from?: string | null | undefined;
  modelIds?: Array<string | number> | null | undefined;
  statuses?: Array<GenerationStatus> | null | undefined;
  to?: string | null | undefined;
};

export type GenerationSort = {
  direction?: SortDirection;
  field?: GenerationSortField;
};

export type GenerationSortField =
  | 'COST'
  | 'CREATED_AT'
  | 'LATENCY'
  | 'TOTAL_TOKENS';

export type GenerationStatus =
  | 'ABORTED'
  | 'ERROR'
  | 'OK';

export type SetAutoTopUpInput = {
  settings: AutoTopUpInput;
  workspaceId: string | number;
};

export type SortDirection =
  | 'ASC'
  | 'DESC';

export type UpdateApiKeyInput = {
  expiresAt?: string | null | undefined;
  /** Replaces the scope. An empty list clears it. */
  modelIds?: Array<string> | null | undefined;
  name?: string | null | undefined;
  requestsPerMinute?: number | null | undefined;
  spendLimitMicros?: string | null | undefined;
  tokensPerMinute?: number | null | undefined;
};

export type UpdatePreferencesInput = {
  archiveEvidence?: boolean | null | undefined;
  desktopNotifications?: boolean | null | undefined;
  emailReceipts?: boolean | null | undefined;
  evidenceRetentionDays?: number | null | undefined;
  notifyOnMeasurementChange?: boolean | null | undefined;
};

export type UpdateProfileInput = {
  /** The display name shown in the console. Blank is not a name. */
  name: string;
};

/** An owner may spend the workspace’s credits; a member may only use them. */
export type WorkspaceRole =
  | 'MEMBER'
  | 'OWNER';

